components.css:
.ds-model{width:112px;display:flex;flex-direction:column;padding:0;text-align:left;border:1px solid var(--studio-line, #e6e2eb);border-radius:12px;background:var(--studio-paper, #ffffff);color:var(--studio-ink, #24232b);cursor:pointer;transition:border-color 180ms ease-out,background-color 180ms ease-out;font:.875rem/1.55 var(--studio-font, Poppins, 'Segoe UI', sans-serif)}
.ds-model:is(:hover,[aria-pressed=true]){border-color:var(--studio-accent, #63469e)}.ds-model[aria-pressed=true]{background:var(--studio-tint, #f0ebfa)}
.ds-art{position:relative;display:grid;place-items:center;width:100%;aspect-ratio:1/.92;overflow:hidden;border-radius:11px 11px 0 0;background:var(--studio-tint, #f0ebfa);color:var(--studio-accent, #63469e)}
.ds-check{position:absolute;top:8px;right:8px;display:grid;place-items:center;width:23px;aspect-ratio:1;border-radius:50%;background:var(--studio-accent, #63469e);color:var(--studio-on-accent, #ffffff)}
.ds-caption{display:grid;gap:2px;padding:9px;font-size:.82rem}.ds-caption small{color:var(--studio-muted, #615e6b);font-size:.7rem}.ds-model:focus-visible { outline: 2px solid var(--studio-accent, #63469e); outline-offset: 3px; }@media(prefers-reduced-motion:reduce){.ds-model{transition:none}}
